const V43_LANGUAGES=['en','uk','ja','fr','it','id','ar','ko','sv','pt','nl','th','km','fil'];
for(const [source,row] of Object.entries(V43_VS_ROWS)){
 if(row.length!==V43_LANGUAGES.length)throw new Error('Incomplete VS summary translation: '+source);
 V43_LANGUAGES.forEach((lang,index)=>{DYNAMIC_TRANSLATIONS[lang][source]=row[index]});
}
// Last War alliance ranks R1–R5 are universal identifiers, never local alphabet letters.
// Preserve the literal R prefix in languages whose dictionary previously transformed it.
for(const [language,label] of [['ar','الرتبة'],['ko','등급'],['th','อันดับ']]){
 DYNAMIC_TRANSLATIONS[language]['Rang R{0}']=label+' R{0}';
 DYNAMIC_TRANSLATIONS[language]['R{0} · {1}']='R{0} · {1}';
 DYNAMIC_TRANSLATIONS[language]['R{0} · {1} · Website-Eigentümerin']='R{0} · {1} · '+({ar:'مالك الموقع',ko:'사이트 소유자',th:'เจ้าของเว็บไซต์'}[language]);
}
const templates=Object.keys(DYNAMIC_TRANSLATIONS.en)
 .sort((a,b)=>b.length-a.length)
 .map(source=>{
  const parts=source.split(/(\{[0-9]+\})/g);
  const markers=[];
  const expr=parts.map(part=>{
   if(/^\{[0-9]+\}$/.test(part)){
    markers.push(Number(part.slice(1,-1)));
    return '(.{1,220}?)';
   }
   return part.replace(/[.*+?^$|{}()[\]\\]/g,'\\$&');
  }).join('');
  return {source,markers,pattern:new RegExp('^'+expr+'$','u')};
 });
export function translateOfficerDynamicText(source,lang='de'){
 if(lang==='de'||!DYNAMIC_TRANSLATIONS[lang]||typeof source!=='string'||source.length>1100)return source;
 for(const template of templates){
  const match=template.pattern.exec(source);
  if(!match)continue;
  // Leading counts are numeric UI values; accepting arbitrary text can rewrite a player's name.
  if(template.source.startsWith('{0}')&&!/^[0-9][0-9., ]*$/u.test(match[1]))continue;
  // Single-metric templates may only consume a numeric stat, never a following
  // date, status sentence, or private name. Leave composite text to safe fragments.
  if(/^(?:Stärke|Spenden) \{0\}$/u.test(template.source)&&!/^[0-9][0-9., ]*$/u.test(match[1]))continue;
  const translated=DYNAMIC_TRANSLATIONS[lang][template.source];
  if(!translated||translated===template.source)continue;
  const values={};
  template.markers.forEach((index,i)=>{values[index]=match[i+1]});
  if(lang==='en' && template.source==='{0} Spieler')return values[0]+(Number(values[0])===1?' player':' Players');
  if(lang==='en' && Number(values[0])===1 && template.source==='{0} Spieler · nach Allianzrang gruppiert')return '1 player · grouped by alliance rank';
  return translated.replace(/\{([0-9]+)\}/g,(_,i)=>values[Number(i)]??'');
 }
 return source;
}
export const OFFICER_DYNAMIC_TEMPLATES=Object.freeze(templates.map(t=>t.source));
